INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(600, 'code', '/koʊd/', 'noun', '{"zh-TW":["密碼；代碼；法規"],"en":["a system of rules or symbols"]}', NULL, 'dress code / zip code', '[{"en":"What''s the door code?","zh-TW":"門的密碼是什麼？"},{"en":"There''s a strict dress code.","zh-TW":"有嚴格的著裝規定。"}]', '{"verb":"code"}', NULL, 1, 600, NULL),
(601, 'coffee', '/ˈkɒfi/', 'noun', '{"zh-TW":["咖啡"],"en":["a hot drink made from roasted beans"]}', NULL, 'coffee shop / cup of coffee', '[{"en":"I need a cup of coffee.","zh-TW":"我需要一杯咖啡。"},{"en":"Let''s meet at the coffee shop.","zh-TW":"我們在咖啡店見面吧。"}]', NULL, NULL, 2, 601, NULL),
(602, 'coherent', '/koʊˈhɪərənt/', 'adjective', '{"zh-TW":["連貫的；一致的"],"en":["logical and consistent; forming a united whole"]}', NULL, 'coherent strategy / coherent plan / coherent message', '[{"en":"The marketing team developed a coherent brand message.","zh-TW":"行銷團隊制定了連貫一致的品牌訊息。"},{"en":"A coherent strategy is essential for aligning team efforts.","zh-TW":"連貫的策略對於整合團隊努力至關重要。"}]', '{"adverb":"coherently","noun":"coherence"}', NULL, 3, 602, 960),
(603, 'coin', '/kɔɪn/', 'noun', '{"zh-TW":["硬幣"],"en":["a small piece of metal used as money"]}', NULL, 'flip a coin / coin a phrase', '[{"en":"I found a coin on the ground.","zh-TW":"我在地上發現了一枚硬幣。"},{"en":"Let''s flip a coin to decide.","zh-TW":"讓我們擲硬幣來決定。"}]', NULL, NULL, 1, 603, NULL),
(604, 'coincide', '/ˌkəʊɪnˈsaɪd/', 'verb', '{"zh-TW":["同時發生；巧合","巧合；同時發生"],"en":["to occur at the same time or place"]}', '{"prefix":{"text":"co-","meaning":"together (一起)"},"root":{"text":"incide","meaning":"fall upon (落入)"},"logic":"一起落入同一點，即「同時發生」。"}', 'coincide with / happen to coincide', '[{"en":"The product launch coincided with a major trade show.","zh-TW":"產品發布與一場大型貿易展同時舉行。"},{"en":"The meeting coincides with my vacation dates.","zh-TW":"會議與我的假期日期衝突。"},{"en":"My vacation coincides with the conference.","zh-TW":"我的假期和會議撞期。"},{"en":"The two events coincided by chance.","zh-TW":"兩件事巧合地同時發生。"}]', '{"noun":"coincidence","adjective":"coincidental"}', NULL, 3, 604, NULL),
(605, 'coinsurance', '/ˌkoʊɪnˈʃʊərəns/', 'noun', '{"zh-TW":["共同保險；自付比例"],"en":["shared insurance where the insured pays a portion of a loss beyond the deductible"]}', NULL, 'coinsurance clause / coinsurance percentage', '[{"en":"The policy has a 20% coinsurance requirement after the deductible.","zh-TW":"保單在免賠額後有20%的共同保險要求。"},{"en":"Coinsurance encourages policyholders to insure properties at full value.","zh-TW":"共同保險鼓勵保單持有人按全值對財產投保。"}]', NULL, NULL, 4, 605, NULL),
(606, 'cold', '/koʊld/', 'adjective', '{"zh-TW":["冷的；冷淡的","冷的；感冒"],"en":["having a low temperature","unfriendly"]}', NULL, 'cold call / cold storage; catch a cold / cold weather', '[{"en":"Cold calling is part of sales training.","zh-TW":"電話開發是銷售訓練的一部分。"},{"en":"Keep the samples in cold storage.","zh-TW":"將樣品放在冷藏庫中。"},{"en":"It''s very cold outside.","zh-TW":"外面很冷。"},{"en":"She caught a cold last week.","zh-TW":"她上星期感冒了。"}]', '{"adjective":"cold","noun":"cold","adverb":"coldly"}', NULL, 1, 606, NULL),
(607, 'collaborate', '/kəˈlæbəreɪt/', 'verb', '{"zh-TW":["合作；協作"],"en":["to work jointly on an activity or project"]}', '{"prefix":{"text":"col-","meaning":"together (一起)"},"root":{"text":"labor","meaning":"work (工作)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"一起工作，即「合作」。"}', 'collaborate with / collaborate on a project', '[{"en":"The two companies collaborated on the research project.","zh-TW":"兩家公司在研究專案上合作。"},{"en":"Teams must collaborate effectively to meet deadlines.","zh-TW":"團隊必須有效合作以趕上截止日期。"}]', '{"noun":"collaboration","adjective":"collaborative"}', NULL, 4, 607, 290),
(608, 'collaboration', '/kəˌlæbəˈreɪʃən/', 'noun', '{"zh-TW":["合作；協作"],"en":["working jointly with others toward a common goal"]}', NULL, 'cross-team collaboration / collaboration tools / foster collaboration', '[{"en":"Collaboration between departments led to an innovative solution.","zh-TW":"各部門之間的合作帶來了創新的解決方案。"},{"en":"Remote tools have improved collaboration across time zones.","zh-TW":"遠端工具改善了跨時區的協作。"}]', '{"verb":"collaborate","adjective":"collaborative"}', NULL, 5, 608, 523),
(609, 'collaborative', 'kəˈlæbərətɪv', 'adjective', '{"zh-TW":["協作的；合作的","共同參與的"],"en":["involving joint effort","working together"]}', NULL, 'collaborative approach/collaborative team', '[{"en":"We encourage a collaborative work culture.","zh-TW":"我們鼓勵協作的工作文化。"}]', '{"noun":"collaboration","adverb":"collaboratively"}', NULL, 5, 609, NULL),
(610, 'collapse', '/kəˈlæps/', 'verb', '{"zh-TW":["崩潰；倒塌","崩塌；倒下"],"en":["to fall down or give way suddenly","to fail suddenly and completely","to fall down suddenly","to fail completely"]}', '{"prefix":{"text":"col-","meaning":"together (一起)"},"root":{"text":"lapse","meaning":"fall (落下)"},"logic":"一起落下，即「崩潰」。"}', 'collapse of / market collapse / building collapse; collapse under pressure / building collapse', '[{"en":"The housing market collapsed during the financial crisis.","zh-TW":"房地產市場在金融危機期間崩盤。"},{"en":"Negotiations collapsed over pricing disagreements.","zh-TW":"談判因價格分歧而破裂。"},{"en":"The bridge collapsed during the earthquake.","zh-TW":"橋樑在地震中倒塌。"},{"en":"The company collapsed due to poor management.","zh-TW":"公司因管理不善而倒閉。"}]', '{"noun":"collapse"}', NULL, 3, 610, NULL),
(611, 'collate', '/kəˈleɪt/', 'verb', '{"zh-TW":["整理；匯編"],"en":["to gather and organize material in a proper order"]}', NULL, 'collate data / collate feedback / collate reports', '[{"en":"She collated all the survey responses into a single spreadsheet.","zh-TW":"她將所有調查回覆整理到一個電子表格中。"},{"en":"The analyst collated data from five different sources.","zh-TW":"分析師從五個不同來源匯編了資料。"}]', '{"noun":"collation","adjective":"collated"}', NULL, 3, 611, NULL),
(612, 'collateral', '/kəˈlætərəl/', 'noun', '{"zh-TW":["擔保品；抵押品"],"en":["an asset pledged as security for a loan"]}', NULL, 'post collateral / collateral requirement / loan collateral', '[{"en":"The bank required collateral before approving the loan.","zh-TW":"銀行在批准貸款前要求提供抵押品。"},{"en":"Property is commonly used as collateral for mortgages.","zh-TW":"財產通常用作抵押貸款的抵押品。"}]', '{"adjective":"collateral"}', NULL, 4, 612, 839),
(613, 'colleague', '/ˈkɒliːɡ/', 'noun', '{"zh-TW":["同事"],"en":["a person with whom one works in a profession"]}', '{"prefix":{"text":"col-","meaning":"together (一起)"},"root":{"text":"league","meaning":"choose/gather (選擇/聚集)"},"logic":"一起被選擇聚集的人，即「同事」。"}', 'work colleague / former colleague', '[{"en":"I discussed the proposal with my colleagues.","zh-TW":"我與同事討論了該提案。"},{"en":"She is well respected by her colleagues.","zh-TW":"她深受同事尊敬。"}]', NULL, NULL, 3, 613, 81),
(614, 'collect', '/kəˈlekt/', 'verb', '{"zh-TW":["收集；收取"],"en":["to bring or gather together","to call for and receive payment"]}', '{"prefix":{"text":"col-","meaning":"together (一起)"},"root":{"text":"lect","meaning":"gather (聚集)"},"logic":"聚集在一起，即「收集」。"}', 'collect data/feedback/payment', '[{"en":"We collect customer feedback through surveys.","zh-TW":"我們透過調查收集客戶反饋。"},{"en":"The agency collects rent on behalf of landlords.","zh-TW":"代理機構代房東收取租金。"}]', '{"noun":"collection"}', NULL, 3, 614, 291),
(615, 'college', '/ˈkɒlɪdʒ/', 'noun', '{"zh-TW":["大學；學院"],"en":["an institution for higher education"]}', NULL, 'go to college / college degree', '[{"en":"She went to college in Boston.","zh-TW":"她在波士頓上大學。"},{"en":"A college degree opens many doors.","zh-TW":"大學學位能開啟很多機會。"}]', NULL, NULL, 3, 615, NULL),
(616, 'color', '/ˈkʌlər/', 'noun', '{"zh-TW":["顏色"],"en":["the appearance of things resulting from light"]}', NULL, 'favorite color / color blind', '[{"en":"What''s your favorite color?","zh-TW":"你最喜歡什麼顏色？"},{"en":"The leaves change color in fall.","zh-TW":"秋天葉子會變色。"}]', '{"adjective":"colorful","verb":"color"}', NULL, 2, 616, NULL),
(617, 'column', '/ˈkɒləm/', 'noun', '{"zh-TW":["欄；柱"],"en":["a vertical division of a page","a pillar supporting a structure"]}', '{"root":{"text":"column","meaning":"pillar (柱子)"},"logic":"源自拉丁語 columna（柱子），引申為報紙或表格的直行。"}', 'newspaper column / column chart / support column', '[{"en":"The data is organized in three columns.","zh-TW":"數據以三欄組織排列。"},{"en":"She writes a weekly column for the newspaper.","zh-TW":"她為報紙寫每週專欄。"}]', '{"noun":"columnist"}', NULL, 2, 617, NULL),
(618, 'combination', '/ˌkɒmbɪˈneɪʃn/', 'noun', '{"zh-TW":["組合；結合"],"en":["a joining of different things"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"bin","meaning":"two (二)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"把兩個以上的東西放在一起的過程，即「組合」。"}', 'a combination of / winning combination', '[{"en":"The dish uses a combination of herbs and spices.","zh-TW":"這道菜使用了多種香草和香料的組合。"},{"en":"Success requires a combination of talent and hard work.","zh-TW":"成功需要天賦和努力的結合。"}]', '{"verb":"combine"}', NULL, 4, 618, 292),
(619, 'come', '/kʌm/', 'verb', '{"zh-TW":["來；到來"],"en":["to move toward","to arrive"]}', NULL, 'come up with / come across', '[{"en":"She came up with a brilliant idea.","zh-TW":"她想出了一個絕妙的點子。"},{"en":"Please come to my office at noon.","zh-TW":"請中午到我的辦公室來。"}]', '{"verb":"come","noun":"outcome","adjective":"incoming"}', NULL, 1, 619, NULL),
(620, 'comedy', '/ˈkɒmədi/', 'noun', '{"zh-TW":["喜劇"],"en":["entertainment that makes people laugh"]}', NULL, 'romantic comedy / comedy show', '[{"en":"I prefer comedies to horror films.","zh-TW":"比起恐怖片我更喜歡喜劇。"},{"en":"The comedy show was hilarious.","zh-TW":"那場喜劇表演太好笑了。"}]', '{"noun2":"comedian"}', NULL, 2, 620, NULL),
(621, 'comfort', '/ˈkʌmfərt/', 'noun', '{"zh-TW":["舒適；安慰"],"en":["a state of ease; something that gives relief","a state of physical ease","something that gives consolation"]}', '{"prefix":{"text":"com-","meaning":"with (一起)"},"root":{"text":"fort","meaning":"strong (強)"},"logic":"使人感到堅強安心，即「安慰」。"}', 'comfort zone / cold comfort; creature comfort / comfort zone / take comfort', '[{"en":"The hotel offers great comfort.","zh-TW":"這家飯店提供極佳的舒適度。"},{"en":"Step out of your comfort zone.","zh-TW":"走出你的舒適圈。"},{"en":"The hotel offers every comfort.","zh-TW":"飯店提供一切舒適設施。"},{"en":"She took comfort in her friend''s words.","zh-TW":"她從朋友的話語中得到安慰。"}]', '{"adjective":"comfortable","verb":"comfort","adverb":"comfortably"}', NULL, 3, 621, NULL),
(622, 'comfortable', 'ˈkʌmftəbəl', 'adjective', '{"zh-TW":["舒適的；自在的","輕鬆的"],"en":["physically relaxed","at ease"]}', NULL, 'comfortable environment/comfortable with', '[{"en":"Are you comfortable with the new system?","zh-TW":"您對新系統感到習慣嗎？"}]', '{"noun":"comfort","adverb":"comfortably"}', NULL, 4, 622, NULL),
(623, 'command', '/kəˈmænd/', 'noun', '{"zh-TW":["命令；指揮"],"en":["an order given","control or authority over something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"mand","meaning":"order (命令)"},"logic":"向大家發出命令，即「指揮」。"}', 'give a command / chain of command / command of', '[{"en":"The officer gave the command to advance.","zh-TW":"軍官下達了前進的命令。"},{"en":"She has a good command of English.","zh-TW":"她的英語掌握得很好。"}]', '{"verb":"command","noun2":"commander"}', NULL, 3, 623, NULL),
(624, 'commence', '/kəˈmens/', 'verb', '{"zh-TW":["開始；著手"],"en":["to begin or start something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"mence","meaning":"begin (開始)"},"logic":"一起開始，即「開始」。"}', 'commence operations/work/proceedings', '[{"en":"Construction will commence in early March.","zh-TW":"工程將於三月初開始。"},{"en":"The meeting commenced at 9 AM sharp.","zh-TW":"會議在上午9點整開始。"}]', '{"noun":"commencement"}', NULL, 3, 624, 654),
(625, 'commencement', '/kəˈmɛnsmənt/', 'noun', '{"zh-TW":["開學；畢業典禮"],"en":["a ceremony at which degrees are conferred"]}', NULL, 'commencement ceremony / commencement speech', '[{"en":"The commencement ceremony will be held outdoors this year.","zh-TW":"今年的畢業典禮將在戶外舉行。"},{"en":"She delivered the commencement speech as valedictorian.","zh-TW":"她以第一名的身份發表了畢業演講。"}]', '{"verb":"commence"}', NULL, 4, 625, 992),
(626, 'comment', '/ˈkɒment/', 'noun', '{"zh-TW":["評論；意見"],"en":["a verbal or written remark expressing an opinion"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"ment","meaning":"mind (心智)"},"logic":"完全出自心智的話，即「評論」。"}', 'make a comment / no comment / comment on', '[{"en":"The manager declined to comment on the rumors.","zh-TW":"經理拒絕對傳聞發表評論。"},{"en":"We welcome comments from our customers.","zh-TW":"我們歡迎客戶的意見。"}]', '{"noun":"commentary"}', NULL, 3, 626, NULL),
(627, 'commerce', '/ˈkɒmɜːrs/', 'noun', '{"zh-TW":["商業；貿易"],"en":["the activity of buying and selling on a large scale"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"merce","meaning":"trade (交易)"},"logic":"一起交易，即「商業」。"}', 'e-commerce / chamber of commerce / international commerce', '[{"en":"E-commerce has transformed the retail industry.","zh-TW":"電子商務已改變了零售產業。"},{"en":"International commerce drives economic growth.","zh-TW":"國際貿易推動經濟成長。"}]', '{"adjective":"commercial","verb":"commercialize"}', NULL, 3, 627, NULL),
(628, 'commission', '/kəˈmɪʃn/', 'noun', '{"zh-TW":["佣金；委員會"],"en":["a payment to an agent","a group appointed for a duty"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"miss","meaning":"send (送)"},"suffix":{"text":"-ion","meaning":"action (動作)"},"logic":"一起被派出的，即「委員會；佣金」。"}', 'sales commission / earn commission / commission a study', '[{"en":"Sales staff earn a 5% commission on each deal.","zh-TW":"銷售人員每筆交易可獲得5%佣金。"},{"en":"The commission will investigate the matter.","zh-TW":"委員會將調查此事。"}]', NULL, NULL, 4, 628, 83),
(629, 'commit', '/kəˈmɪt/', 'verb', '{"zh-TW":["承諾；投入","犯（罪）","承諾；犯(罪)"],"en":["to pledge or dedicate oneself to","to carry out something illegal","to pledge or dedicate","to carry out a crime"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"mit","meaning":"send (送)"},"logic":"完全送出自己，即「承諾」。"}', 'commit to / commit resources / commit a crime; commit to / commit a crime / fully committed', '[{"en":"The company committed $1 million to the initiative.","zh-TW":"公司投入100萬美元於該計畫。"},{"en":"We are committed to delivering quality service.","zh-TW":"我們致力於提供優質服務。"},{"en":"She committed herself to finishing the project.","zh-TW":"她承諾完成這個專案。"},{"en":"He committed a serious offense.","zh-TW":"他犯了一項嚴重罪行。"}]', '{"noun":"commitment","adjective":"committed"}', NULL, 2, 629, 730),
(630, 'commitment', '/kəˈmɪtmənt/', 'noun', '{"zh-TW":["承諾；投入"],"en":["a pledge or undertaking","dedication to a cause"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"mit","meaning":"send (送)"},"suffix":{"text":"-ment","meaning":"state (狀態)"},"logic":"完全送出自己的狀態，即「承諾」。"}', 'make a commitment / strong commitment / commitment to quality', '[{"en":"Our commitment to quality is unwavering.","zh-TW":"我們對品質的承諾堅定不移。"},{"en":"The project requires a significant time commitment.","zh-TW":"該專案需要投入大量時間。"}]', '{"verb":"commit","adjective":"committed"}', NULL, 4, 630, 84),
(631, 'committee', '/kəˈmɪti/', 'noun', '{"zh-TW":["委員會"],"en":["a group of people appointed for a specific function"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"mit","meaning":"send (送)"},"suffix":{"text":"-ee","meaning":"those who (…的人們)"},"logic":"一起被派出處理事務的人，即「委員會」。"}', 'steering committee / advisory committee / committee meeting', '[{"en":"The committee meets monthly to review progress.","zh-TW":"委員會每月開會檢視進度。"},{"en":"A new committee was formed to address the issue.","zh-TW":"成立了新委員會來處理此議題。"}]', NULL, NULL, 3, 631, NULL),
(632, 'commodities', '/kəˈmɒdɪtiz/', 'noun', '{"zh-TW":["大宗商品；原物料"],"en":["basic goods such as metals, energy, and agricultural products traded in bulk"]}', NULL, 'commodity prices / trade commodities / commodity market', '[{"en":"Rising commodity prices pushed up manufacturing costs.","zh-TW":"大宗商品價格上漲推高了製造成本。"},{"en":"Oil and copper are among the most widely traded commodities.","zh-TW":"石油和銅是交易最廣泛的大宗商品之一。"}]', '{"singular":"commodity","adjective":"commodity"}', NULL, 4, 632, NULL),
(633, 'commodity', '/kəˈmɒdəti/', 'noun', '{"zh-TW":["商品；大宗物資"],"en":["a raw material or agricultural product that can be bought and sold"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"mod","meaning":"measure/fit (衡量/適合)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"完全適合交易的物品，即「商品」。"}', 'commodity prices / commodity market / basic commodities', '[{"en":"Oil is one of the most traded commodities.","zh-TW":"石油是交易量最大的商品之一。"},{"en":"Commodity prices fluctuate based on supply and demand.","zh-TW":"商品價格根據供需波動。"}]', NULL, NULL, 3, 633, 840),
(634, 'common', '/ˈkɒmən/', 'adjective', '{"zh-TW":["常見的；共同的"],"en":["happening often","shared by two or more","happening often; shared by all"]}', NULL, 'common ground / common sense; common sense / in common', '[{"en":"This is a common mistake.","zh-TW":"這是一個常見的錯誤。"},{"en":"We found common ground on the issue.","zh-TW":"我們在這個問題上找到了共識。"},{"en":"Colds are common in winter.","zh-TW":"感冒在冬天很常見。"},{"en":"We have a lot in common.","zh-TW":"我們有很多共同點。"}]', '{"adjective":"common","adverb":"commonly","noun":"commonality"}', NULL, 2, 634, NULL),
(635, 'communicate', '/kəˈmjuːnɪkeɪt/', 'verb', '{"zh-TW":["溝通；傳達"],"en":["to share or exchange information"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"munic","meaning":"share (分享)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"一起分享，即「溝通」。"}', 'communicate effectively / communicate with', '[{"en":"It''s important to communicate clearly with clients.","zh-TW":"與客戶清楚溝通很重要。"},{"en":"The change was communicated to all employees.","zh-TW":"變更已傳達給所有員工。"}]', '{"noun":"communication"}', NULL, 4, 635, 293),
(636, 'communication', 'kəˈmjuːnɪkeɪʃən', 'noun', '{"zh-TW":["溝通；通訊","交流"],"en":["the exchange of information","a way of sharing messages"]}', NULL, 'effective communication/open communication', '[{"en":"Effective communication is key to success.","zh-TW":"有效的溝通是成功的關鍵。"}]', '{"verb":"communicate","adjective":"communicative","adverb":"communicatively"}', NULL, 5, 636, NULL),
(637, 'communiqué', '/kəˈmjuːnɪkeɪ/', 'noun', '{"zh-TW":["公報；官方聲明"],"en":["an official announcement or statement, especially from a government or organization"]}', NULL, 'issue a communiqué / joint communiqué / press communiqué', '[{"en":"A joint communiqué was released after the trade summit.","zh-TW":"貿易峰會後發佈了聯合公報。"},{"en":"The communiqué outlined the agreed terms of the partnership.","zh-TW":"公報概述了夥伴關係的商定條款。"}]', NULL, NULL, 4, 637, NULL),
(638, 'community', '/kəˈmjuːnəti/', 'noun', '{"zh-TW":["社區；社群"],"en":["a group of people living in the same area or sharing characteristics"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"mun","meaning":"service/duty (服務)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"一起服務的狀態，即「社區」。"}', 'local community / business community / online community', '[{"en":"The company supports the local community through donations.","zh-TW":"公司透過捐款支持當地社區。"},{"en":"The business community welcomed the new regulations.","zh-TW":"商業社群歡迎新法規。"}]', NULL, NULL, 3, 638, NULL),
(639, 'commute', '/kəˈmjuːt/', 'verb', '{"zh-TW":["通勤"],"en":["to travel regularly between home and work"]}', NULL, 'daily commute / commute by train', '[{"en":"She commutes to the office by subway every day.","zh-TW":"她每天搭地鐵上班。"},{"en":"The commute from the suburbs takes about an hour.","zh-TW":"從郊區通勤約需一小時。"}]', '{"noun":"commuter","adjective":"commutable"}', NULL, 3, 639, NULL),
(640, 'company', '/ˈkʌmpəni/', 'noun', '{"zh-TW":["公司；企業"],"en":["a commercial business organization"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pan","meaning":"bread (麵包)"},"suffix":{"text":"-y","meaning":"noun ending (名詞字尾)"},"logic":"一起吃麵包的人（夥伴），即「公司」。"}', 'company policy / parent company / run a company', '[{"en":"The company employs over 10,000 people worldwide.","zh-TW":"公司在全球僱用超過10,000人。"},{"en":"She started her own company at age 25.","zh-TW":"她25歲時創辦了自己的公司。"}]', NULL, NULL, 3, 640, 294),
(641, 'comparables', '/kəmˈpærəblz/', 'noun', '{"zh-TW":["可比公司；參考案例"],"en":["companies or transactions used as benchmarks for valuation or analysis"]}', NULL, 'identify comparables / trading comparables', '[{"en":"Analysts selected three comparables for the acquisition valuation.","zh-TW":"分析師為收購估值選擇了三個可比公司。"},{"en":"Comparables-based valuation adjusts for differences in size and growth rates.","zh-TW":"基於可比公司的估值對規模和增長率的差異進行了調整。"}]', '{"synonym":"comps"}', NULL, 4, 641, NULL),
(642, 'compare', '/kəmˈpeər/', 'verb', '{"zh-TW":["比較；對照","比較"],"en":["to examine similarities and differences between","to examine the similarities and differences","to estimate similarities or differences"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"par","meaning":"equal (相等)"},"logic":"放在一起看是否相等，即「比較」。"}', 'compare with/to / compare prices; compare with / compare to; compare with / compare to / compared to', '[{"en":"Let''s compare the two proposals side by side.","zh-TW":"讓我們並排比較兩份提案。"},{"en":"Compared to last year, sales have increased 20%.","zh-TW":"與去年相比，銷售增長了20%。"},{"en":"Compare these two products.","zh-TW":"比較這兩個產品。"},{"en":"Compared to last year, sales rose.","zh-TW":"與去年相比，銷售額上升了。"},{"en":"Compare these two products before buying.","zh-TW":"購買前先比較這兩個產品。"},{"en":"Compared to last year, sales are up 20%.","zh-TW":"與去年相比，銷售增長了20%。"}]', '{"noun":"comparison","adjective":"comparable","adjective2":"comparative"}', NULL, 3, 642, 295),
(643, 'comparison', 'kəmˈpærɪsən', 'noun', '{"zh-TW":["比較；對比","類比"],"en":["the act of comparing","a similarity or difference"]}', NULL, 'make a comparison/by comparison', '[{"en":"By comparison, our prices are lower.","zh-TW":"相比之下，我們的價格更低。"}]', '{"verb":"compare","adjective":"comparable","adverb":"comparably"}', NULL, 4, 643, 525),
(644, 'compassion', '/kəmˈpæʃn/', 'noun', '{"zh-TW":["同情心；憐憫"],"en":["sympathy and concern for the sufferings of others"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pass","meaning":"suffer (受苦)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"一起感受痛苦，即「同情」。"}', 'show compassion / have compassion for', '[{"en":"She showed great compassion for the homeless.","zh-TW":"她對無家可歸的人表現出極大的同情。"},{"en":"A good leader leads with compassion.","zh-TW":"好的領導者以同理心領導。"}]', '{"adjective":"compassionate"}', NULL, 4, 644, NULL),
(645, 'compatible', '/kəmˈpætəbl/', 'adjective', '{"zh-TW":["相容的；兼容的","相容的"],"en":["able to exist or work together without conflict","able to work together without problems"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pat","meaning":"suffer/feel (感受)"},"suffix":{"text":"-ible","meaning":"able to (能夠)"},"logic":"能夠一起感受的，即「相容的」。"}', 'compatible with / compatible systems; compatible with / backward compatible', '[{"en":"The new software is compatible with all devices.","zh-TW":"新軟體與所有裝置相容。"},{"en":"Make sure the parts are compatible before ordering.","zh-TW":"訂購前請確認零件相容。"},{"en":"Is this software compatible with Mac?","zh-TW":"這軟體和Mac相容嗎？"},{"en":"The new version is backward compatible.","zh-TW":"新版本向下相容。"}]', '{"noun":"compatibility"}', NULL, 4, 645, NULL),
(646, 'compel', '/kəmˈpel/', 'verb', '{"zh-TW":["強迫；迫使"],"en":["to force or oblige someone to do something"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"pel","meaning":"drive (驅使)"},"logic":"完全驅使，即「強迫」。"}', 'compel sb to do / feel compelled', '[{"en":"Economic pressures compelled the company to downsize.","zh-TW":"經濟壓力迫使公司裁員。"},{"en":"She felt compelled to report the safety violation.","zh-TW":"她覺得不得不舉報安全違規。"}]', '{"adjective":"compelling"}', NULL, 2, 646, NULL),
(647, 'compensate', '/ˈkɒmpenseɪt/', 'verb', '{"zh-TW":["補償；賠償"],"en":["to give something to make up for loss or damage"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"pens","meaning":"weigh (稱重)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"完全衡量損失並補回，即「補償」。"}', 'compensate for / compensate employees', '[{"en":"The company compensated employees for overtime work.","zh-TW":"公司補償員工加班工作。"},{"en":"Nothing can compensate for the loss of reputation.","zh-TW":"沒有什麼能彌補名譽的損失。"},{"en":"The company compensated workers for overtime.","zh-TW":"公司補償了員工的加班費。"},{"en":"Nothing can compensate for the loss of a loved one.","zh-TW":"沒有什麼能彌補失去親人的痛苦。"}]', '{"noun":"compensation"}', NULL, 4, 647, 656),
(648, 'compensation', '/ˌkɒmpənˈseɪʃən/', 'noun', '{"zh-TW":["薪酬；補償"],"en":["total financial and non-financial rewards provided to employees"]}', NULL, 'compensation package / compensation structure / executive compensation', '[{"en":"The compensation package includes salary, bonuses, and benefits.","zh-TW":"薪酬方案包括薪資、獎金和福利。"},{"en":"Competitive compensation is key to attracting top talent.","zh-TW":"具競爭力的薪酬是吸引頂尖人才的關鍵。"}]', '{"verb":"compensate","adjective":"compensatory"}', NULL, 4, 648, 85),
(649, 'compete', '/kəmˈpiːt/', 'verb', '{"zh-TW":["競爭","競爭；比賽"],"en":["to strive to gain something by defeating others","to try to win something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pete","meaning":"seek (尋求)"},"logic":"一起尋求同一目標，即「競爭」。"}', 'compete with/against / compete for; compete against / compete for', '[{"en":"Local firms must compete with international corporations.","zh-TW":"本地企業必須與國際公司競爭。"},{"en":"Ten candidates competed for the position.","zh-TW":"十位候選人競爭該職位。"},{"en":"Ten teams will compete in the tournament.","zh-TW":"十支隊伍將參加比賽。"},{"en":"Companies compete for customers.","zh-TW":"公司為爭取客戶而競爭。"}]', '{"noun":"competition","adjective":"competitive","noun2":"competitor"}', NULL, 3, 649, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(650, 'competent', '/ˈkɒmpɪtənt/', 'adjective', '{"zh-TW":["能勝任的；稱職的"],"en":["having the necessary ability or knowledge"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"pet","meaning":"seek (尋求)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"完全具備所尋求的能力，即「稱職的」。"}', 'highly competent / competent in', '[{"en":"She is a highly competent project manager.","zh-TW":"她是一位非常稱職的專案經理。"},{"en":"The candidate must be competent in data analysis.","zh-TW":"候選人必須擅長數據分析。"}]', '{"noun":"competence"}', NULL, 3, 650, NULL),
(651, 'competition', 'ˌkɒmpɪˈtɪʃən', 'noun', '{"zh-TW":["競爭；比賽","對手"],"en":["the activity of competing","a contest"]}', NULL, 'market competition/fair competition', '[{"en":"The competition in this industry is fierce.","zh-TW":"這個行業的競爭很激烈。"}]', '{"verb":"compete","adjective":"competitive","adverb":"competitively"}', NULL, 4, 651, 526),
(652, 'competitive', 'kəmˈpɛtɪtɪv', 'adjective', '{"zh-TW":["競爭性的；有競爭力的","好勝的"],"en":["involving competition","able to compete"]}', NULL, 'competitive price/competitive market', '[{"en":"We offer competitive pricing.","zh-TW":"我們提供有競爭力的定價。"}]', '{"noun":"competition","adverb":"competitively"}', NULL, 4, 652, 296),
(653, 'competitiveness', '/kəmˈpetɪtɪvnəs/', 'noun', '{"zh-TW":["競爭力"],"en":["the quality of being as good as or better than others"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pet","meaning":"seek (尋求)"},"suffix":{"text":"-iveness","meaning":"state (狀態)"},"logic":"一起尋求目標的能力狀態，即「競爭力」。"}', 'global competitiveness / enhance competitiveness / price competitiveness', '[{"en":"Innovation is key to maintaining competitiveness.","zh-TW":"創新是保持競爭力的關鍵。"},{"en":"Lower costs improve our price competitiveness.","zh-TW":"降低成本提升我們的價格競爭力。"}]', '{"adjective":"competitive","verb":"compete"}', NULL, 5, 653, NULL),
(654, 'compile', '/kəmˈpaɪl/', 'verb', '{"zh-TW":["彙編；匯集","編譯；彙編","編纂；彙整"],"en":["to collect and assemble information from various sources","to convert code into machine language","to produce by assembling information"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pile","meaning":"heap (堆積)"},"logic":"一起堆積，即「彙編」。"}', 'compile a report/list/database; compile code / compile a list; compile data / compile a list / compile a report', '[{"en":"The assistant compiled the data into a report.","zh-TW":"助理將數據彙編成報告。"},{"en":"We compiled a list of potential suppliers.","zh-TW":"我們匯集了一份潛在供應商清單。"},{"en":"The code failed to compile.","zh-TW":"程式碼編譯失敗了。"},{"en":"She compiled a list of errors.","zh-TW":"她彙整了一份錯誤清單。"},{"en":"She compiled a list of potential clients.","zh-TW":"她彙整了一份潛在客戶名單。"},{"en":"The report was compiled from various sources.","zh-TW":"報告是從各種來源彙整而成。"}]', '{"noun":"compilation","noun2":"compilation"}', NULL, 3, 654, 657),
(655, 'complain', '/kəmˈpleɪn/', 'verb', '{"zh-TW":["抱怨；投訴"],"en":["to say you are unhappy about something"]}', NULL, 'complain about / complain to', '[{"en":"She complained about the noise.","zh-TW":"她抱怨噪音。"},{"en":"Customers complained to the manager.","zh-TW":"顧客向經理投訴。"}]', '{"noun":"complaint"}', NULL, 3, 655, NULL),
(656, 'complaint', '/kəmˈpleɪnt/', 'noun', '{"zh-TW":["投訴；抱怨"],"en":["an expression of dissatisfaction"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"plaint","meaning":"lament (悲嘆)"},"logic":"一起發出悲嘆，即「抱怨」。"}', 'file a complaint / customer complaint', '[{"en":"We received several complaints about the noise.","zh-TW":"我們收到了幾起關於噪音的投訴。"},{"en":"She filed a complaint with the manager.","zh-TW":"她向經理提出投訴。"}]', '{"verb":"complain","noun":"complainant"}', NULL, 3, 656, 86),
(657, 'complement', '/ˈkɒmplɪment/', 'verb', '{"zh-TW":["補充；相輔相成"],"en":["to add to something to enhance or improve it"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"ple","meaning":"fill (填)"},"suffix":{"text":"-ment","meaning":"thing (事物)"},"logic":"完全填滿的東西，即「補充」。"}', 'complement each other / complement skills', '[{"en":"The two departments complement each other well.","zh-TW":"兩個部門相輔相成。"},{"en":"Her skills complement those of her business partner.","zh-TW":"她的技能與商業夥伴的互補。"}]', '{"adjective":"complementary"}', NULL, 4, 657, 527),
(658, 'complete', '/kəmˈpliːt/', 'verb', '{"zh-TW":["完成；完整的"],"en":["to finish","having all parts"]}', NULL, 'complete a task / complete set', '[{"en":"Please complete the form by Friday.","zh-TW":"請在週五前填好表格。"},{"en":"The renovation is now complete.","zh-TW":"翻新工程已經完成了。"}]', '{"verb":"complete","adjective":"complete","noun":"completion","adverb":"completely"}', NULL, 3, 658, 16),
(659, 'complex', '/ˈkɒmpleks/', 'adjective', '{"zh-TW":["複雜的"],"en":["consisting of many different parts; not easy to understand"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"plex","meaning":"weave (編織)"},"logic":"編織在一起的，即「複雜的」。"}', 'complex issue/system/process', '[{"en":"International tax law is extremely complex.","zh-TW":"國際稅法極其複雜。"},{"en":"The project involves complex logistics.","zh-TW":"該專案涉及複雜的物流。"}]', '{"noun":"complexity"}', NULL, 3, 659, NULL),
(660, 'compliance', '/kəmˈplaɪəns/', 'noun', '{"zh-TW":["合規；遵守"],"en":["the act of conforming to a rule or standard"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"pli","meaning":"fold/fill (折疊/充滿)"},"suffix":{"text":"-ance","meaning":"state (狀態)"},"logic":"完全充滿順從的狀態，即「合規」。"}', 'regulatory compliance / in compliance with / compliance officer', '[{"en":"The company is in full compliance with all regulations.","zh-TW":"公司完全遵守所有法規。"},{"en":"A compliance officer monitors adherence to policies.","zh-TW":"合規官監督政策遵守情況。"}]', '{"verb":"comply","adjective":"compliant"}', NULL, 4, 660, 297),
(661, 'compliant', 'kəmˈplaɪənt', 'adjective', '{"zh-TW":["合規的；遵從的","符合規定的"],"en":["meeting required standards","following rules"]}', NULL, 'tax compliant/regulatory compliant', '[{"en":"All products must be fully compliant.","zh-TW":"所有產品必須完全合規。"}]', '{"verb":"comply","noun":"compliance","adverb":"compliantly"}', NULL, 3, 661, NULL),
(662, 'complicate', '/ˈkɒmplɪkeɪt/', 'verb', '{"zh-TW":["使複雜化"],"en":["to make something more difficult or complex"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"plic","meaning":"fold (折疊)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使東西摺疊在一起，即「使複雜」。"}', 'complicate matters / further complicate', '[{"en":"His arrival only complicated matters.","zh-TW":"他的到來只是讓事情更複雜。"},{"en":"Don''t complicate things unnecessarily.","zh-TW":"不要把事情不必要地複雜化。"}]', '{"noun":"complication","adjective":"complicated"}', NULL, 4, 662, NULL),
(663, 'complimentary', '/ˌkɒmplɪˈmɛntəri/', 'adjective', '{"zh-TW":["免費的；贈送的"],"en":["given free of charge"]}', NULL, 'complimentary breakfast / complimentary service', '[{"en":"The hotel offers a complimentary breakfast for guests.","zh-TW":"飯店為住客提供免費早餐。"},{"en":"Complimentary wifi is available in all rooms.","zh-TW":"所有房間均提供免費無線網路。"}]', NULL, NULL, 5, 663, NULL),
(664, 'comply', '/kəmˈplaɪ/', 'verb', '{"zh-TW":["遵守；符合"],"en":["to act in accordance with a rule or request"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"ply","meaning":"fold/fill (折疊/充滿)"},"logic":"完全充滿順從，即「遵守」。"}', 'comply with regulations/standards/requirements', '[{"en":"All products must comply with safety standards.","zh-TW":"所有產品必須符合安全標準。"},{"en":"Failure to comply may result in penalties.","zh-TW":"不遵守可能導致罰款。"}]', '{"noun":"compliance","adjective":"compliant"}', NULL, 2, 664, 87),
(665, 'component', '/kəmˈpəʊnənt/', 'noun', '{"zh-TW":["組件；成分"],"en":["a part or element of a larger whole"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pon","meaning":"put (放置)"},"suffix":{"text":"-ent","meaning":"thing (事物)"},"logic":"放置在一起的東西，即「組件」。"}', 'key component / component parts / electronic component', '[{"en":"Quality control is a key component of manufacturing.","zh-TW":"品質控制是製造業的關鍵組成部分。"},{"en":"The device contains over 500 electronic components.","zh-TW":"該裝置包含超過500個電子元件。"}]', NULL, NULL, 3, 665, 298),
(666, 'compose', '/kəmˈpəʊz/', 'verb', '{"zh-TW":["組成；撰寫","作曲；組成"],"en":["to make up the whole","to write or create","to write music","to make up or form something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pose","meaning":"put/place (放置)"},"logic":"一起放置，即「組成」。"}', 'be composed of / compose a letter; compose a symphony / compose oneself', '[{"en":"The committee is composed of 12 members.","zh-TW":"委員會由12名成員組成。"},{"en":"She composed a formal response to the complaint.","zh-TW":"她撰寫了對投訴的正式回覆。"},{"en":"Beethoven composed nine symphonies.","zh-TW":"貝多芬創作了九首交響曲。"}]', '{"noun":"composition","noun2":"composition"}', NULL, 3, 666, NULL),
(667, 'compost', '/ˈkɒmpɒst/', 'noun', '{"zh-TW":["堆肥"],"en":["decayed organic matter used as fertilizer"]}', NULL, 'make compost / compost bin', '[{"en":"Food scraps can be turned into compost for the garden.","zh-TW":"廚餘可以製成花園用的堆肥。"},{"en":"The restaurant donates food waste to a composting program.","zh-TW":"餐廳將廚餘捐給堆肥計劃。"}]', '{"verb":"compost","adjective":"composted"}', NULL, 3, 667, NULL),
(668, 'comprehensive', '/ˌkɒmprɪˈhensɪv/', 'adjective', '{"zh-TW":["全面的；綜合的"],"en":["including all or nearly all aspects of something"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"prehens","meaning":"grasp (抓住)"},"suffix":{"text":"-ive","meaning":"having quality (具有特質)"},"logic":"完全抓住所有面向的，即「全面的」。"}', 'comprehensive plan/review/report', '[{"en":"We conducted a comprehensive review of all policies.","zh-TW":"我們對所有政策進行了全面審查。"},{"en":"The package includes comprehensive health insurance.","zh-TW":"該方案包括全面的健康保險。"}]', '{"adverb":"comprehensively"}', NULL, 5, 668, 299),
(669, 'comprise', '/kəmˈpraɪz/', 'verb', '{"zh-TW":["包含；由…組成"],"en":["to consist of; to be made up of"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"prise","meaning":"take (拿取)"},"logic":"一起拿取在內，即「包含」。"}', 'comprise of / be comprised of', '[{"en":"The team comprises specialists from various departments.","zh-TW":"團隊由各部門的專家組成。"},{"en":"Women comprise 45% of the workforce.","zh-TW":"女性占勞動力的45%。"}]', NULL, NULL, 3, 669, NULL),
(670, 'compromise', '/ˈkɒmprəmaɪz/', 'noun', '{"zh-TW":["妥協；折衷"],"en":["an agreement reached by each side giving up something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"promise","meaning":"promise (承諾)"},"logic":"一起做出讓步承諾，即「妥協」。"}', 'reach a compromise / make a compromise', '[{"en":"Both sides reached a compromise on the pricing.","zh-TW":"雙方在定價上達成了妥協。"},{"en":"Quality should never be compromised for speed.","zh-TW":"不應為了速度而犧牲品質。"}]', NULL, NULL, 4, 670, NULL),
(671, 'compulsory', '/kəmˈpʌlsəri/', 'adjective', '{"zh-TW":["強制的；義務的","強制的；必修的"],"en":["required by law or rule; obligatory","required by law or rule"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"puls","meaning":"drive (驅使)"},"suffix":{"text":"-ory","meaning":"relating to (有關的)"},"logic":"完全被驅使的，即「強制的」。"}', 'compulsory training/education/insurance; compulsory education / compulsory subject', '[{"en":"Attendance at the safety training is compulsory.","zh-TW":"安全訓練的出席是強制性的。"},{"en":"The company has compulsory retirement at age 65.","zh-TW":"公司規定65歲強制退休。"},{"en":"Education is compulsory until age 16.","zh-TW":"教育在16歲前是義務的。"},{"en":"Math is a compulsory subject.","zh-TW":"數學是必修科目。"}]', '{"verb":"compel"}', NULL, 4, 671, NULL),
(672, 'computer', '/kəmˈpjuːtər/', 'noun', '{"zh-TW":["電腦"],"en":["an electronic device for processing data"]}', NULL, 'computer system / computer skills', '[{"en":"All employees need basic computer skills.","zh-TW":"所有員工都需要基本的電腦技能。"},{"en":"The computer system crashed this morning.","zh-TW":"電腦系統今早當機了。"}]', '{"noun":"computer","verb":"compute","noun2":"computation"}', NULL, 3, 672, NULL),
(673, 'conceal', '/kənˈsiːl/', 'verb', '{"zh-TW":["隱藏；隱瞞"],"en":["to keep from sight; to hide"]}', '{"prefix":{"text":"con-","meaning":"completely (完全)"},"root":{"text":"ceal","meaning":"hide (藏)"},"logic":"完全藏起來，即「隱藏」。"}', 'conceal information/facts/identity', '[{"en":"The report accused the firm of concealing financial losses.","zh-TW":"報告指控該公司隱瞞財務虧損。"},{"en":"It is illegal to conceal material information from investors.","zh-TW":"向投資者隱瞞重要資訊是違法的。"}]', '{"noun":"concealment"}', NULL, 3, 673, NULL),
(674, 'concealment', '/kənˈsiːlmənt/', 'noun', '{"zh-TW":["隱瞞；隱藏"],"en":["the deliberate withholding of material information from another party"]}', NULL, 'material concealment / concealment of facts', '[{"en":"Concealment of a known defect may invalidate the insurance policy.","zh-TW":"隱瞞已知缺陷可能使保險單失效。"},{"en":"The auditors discovered the concealment of liabilities in the accounts.","zh-TW":"審計師在帳目中發現了對負債的隱瞞。"}]', '{"verb":"conceal"}', NULL, 4, 674, NULL),
(675, 'concentrate', '/ˈkɒnsntreɪt/', 'verb', '{"zh-TW":["集中；專注"],"en":["to focus attention or effort on something","to focus all attention on something"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"centr","meaning":"center (中心)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使聚集到中心，即「集中」。"}', 'concentrate on / concentrate efforts; concentrate on / unable to concentrate', '[{"en":"We should concentrate our efforts on core business.","zh-TW":"我們應該將精力集中在核心業務上。"},{"en":"The company decided to concentrate on the domestic market.","zh-TW":"公司決定專注於國內市場。"},{"en":"I need to concentrate on my work.","zh-TW":"我需要專注在工作上。"},{"en":"She couldn''t concentrate because of the noise.","zh-TW":"因為噪音她無法集中精神。"}]', '{"noun":"concentration"}', NULL, 4, 675, 731),
(676, 'concept', '/ˈkɒnsept/', 'noun', '{"zh-TW":["概念；構想","概念"],"en":["an abstract idea or general notion"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"cept","meaning":"take/seize (抓取)"},"logic":"完全抓住的想法，即「概念」。"}', 'concept of / new concept / concept design; basic concept / new concept / concept of', '[{"en":"The concept of remote work has gained widespread acceptance.","zh-TW":"遠端工作的概念已獲得廣泛接受。"},{"en":"The team presented a new product concept.","zh-TW":"團隊展示了一個新的產品概念。"},{"en":"The concept is simple but effective.","zh-TW":"概念簡單但有效。"},{"en":"He introduced a new concept in design.","zh-TW":"他引入了一個新的設計概念。"}]', '{"adjective":"conceptual"}', NULL, 3, 676, 300),
(677, 'concern', '/kənˈsɜːrn/', 'noun', '{"zh-TW":["關注；擔憂","事業","擔心；關切"],"en":["a matter of interest or importance","worry or anxiety","worry; something that causes anxiety"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"cern","meaning":"sift/separate (篩選)"},"logic":"完全篩選注意的事，即「關注」。"}', 'raise concerns / major concern / concern about; major concern / express concern / growing concern', '[{"en":"Safety is our primary concern.","zh-TW":"安全是我們首要關注的事項。"},{"en":"Several employees raised concerns about the policy.","zh-TW":"幾位員工對該政策提出了擔憂。"},{"en":"Safety is our primary concern.","zh-TW":"安全是我們最主要的關切。"},{"en":"There is growing concern about climate change.","zh-TW":"對氣候變遷的擔憂日益增加。"}]', '{"adjective":"concerned","verb":"concern","adjective2":"concerning"}', NULL, 3, 677, 88),
(678, 'concerned', 'kənˈsɜːrnd', 'adjective', '{"zh-TW":["擔憂的；關切的","相關的"],"en":["worried about something","involved in something"]}', NULL, 'be concerned about/parties concerned', '[{"en":"Management is concerned about the results.","zh-TW":"管理層對結果感到擔憂。"}]', '{"verb":"concern","noun":"concern","adverb":"concernedly"}', NULL, 3, 678, NULL),
(679, 'concert', '/ˈkɒnsərt/', 'noun', '{"zh-TW":["音樂會；演唱會"],"en":["a public musical performance"]}', NULL, 'concert hall / rock concert', '[{"en":"We went to a concert last night.","zh-TW":"我們昨晚去了演唱會。"},{"en":"The concert was sold out.","zh-TW":"演唱會門票售罄了。"}]', NULL, NULL, 3, 679, NULL),
(680, 'concession', '/kənˈsɛʃən/', 'noun', '{"zh-TW":["讓步；特許；優惠"],"en":["something granted as a compromise"]}', NULL, 'make a concession / price concession', '[{"en":"Both parties made concessions to reach the agreement.","zh-TW":"雙方做出了讓步以達成協議。"},{"en":"The company offered a price concession to secure the contract.","zh-TW":"公司提供了價格優惠以確保合約。"}]', '{"verb":"concede","adjective":"concessionary"}', NULL, 4, 680, NULL),
(681, 'concierge', '/ˌkɒnsiˈɛərʒ/', 'noun', '{"zh-TW":["禮賓人員"],"en":["a hotel employee who assists guests with services"]}', NULL, 'hotel concierge / ask the concierge', '[{"en":"The concierge recommended a nearby restaurant.","zh-TW":"禮賓員推薦了附近的餐廳。"},{"en":"Ask the concierge to arrange a taxi for you.","zh-TW":"請禮賓員幫您叫計程車。"}]', NULL, NULL, 3, 681, NULL),
(682, 'concise', 'kənˈsaɪs', 'adjective', '{"zh-TW":["簡潔的；簡明的","扼要的"],"en":["expressing much in few words","brief but clear"]}', NULL, 'concise report/concise summary', '[{"en":"Please write a concise summary.","zh-TW":"請寫一個簡明的摘要。"}]', '{"noun":"conciseness","adverb":"concisely"}', NULL, 3, 682, 843),
(683, 'conclude', '/kənˈkluːd/', 'verb', '{"zh-TW":["結論；結束","總結；結束"],"en":["to bring to an end","to arrive at a judgment or opinion","to arrive at a judgment"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"clude","meaning":"close (關閉)"},"logic":"完全關閉，即「結束、下結論」。"}', 'conclude that / conclude a deal/meeting; conclude a meeting / conclude that', '[{"en":"The study concluded that the treatment was effective.","zh-TW":"研究得出結論認為該治療有效。"},{"en":"Negotiations were concluded successfully.","zh-TW":"談判成功結束。"},{"en":"The meeting concluded at 5 p.m.","zh-TW":"會議在下午五點結束。"},{"en":"The study concluded that exercise improves mental health.","zh-TW":"研究總結運動能改善心理健康。"}]', '{"noun":"conclusion","adjective":"conclusive"}', NULL, 3, 683, NULL),
(684, 'conclusion', 'kənˈkluːʒən', 'noun', '{"zh-TW":["結論；結尾","結果"],"en":["a judgment reached by reasoning","the end of something"]}', NULL, 'draw a conclusion/in conclusion', '[{"en":"In conclusion, the project was successful.","zh-TW":"總之，這個專案是成功的。"}]', '{"verb":"conclude","adjective":"conclusive","adverb":"conclusively"}', NULL, 4, 684, 301),
(685, 'concrete', '/ˈkɒŋkriːt/', 'adjective', '{"zh-TW":["具體的；確切的"],"en":["existing in a material form; specific and definite"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"crete","meaning":"grow (生長)"},"logic":"一起生長凝固的，即「具體的」。"}', 'concrete evidence/plan/example', '[{"en":"Do you have any concrete evidence to support your claim?","zh-TW":"你有任何具體證據支持你的說法嗎？"},{"en":"We need a concrete plan, not just ideas.","zh-TW":"我們需要具體計畫，而不只是想法。"}]', NULL, NULL, 3, 685, 961),
(686, 'condiment', '/ˈkɒndɪmənt/', 'noun', '{"zh-TW":["調味料；佐料"],"en":["a sauce or seasoning added to food"]}', NULL, 'table condiment / common condiment', '[{"en":"Salt, pepper, and ketchup are common table condiments.","zh-TW":"鹽、胡椒和番茄醬是常見的餐桌調味料。"},{"en":"The restaurant provides a variety of condiments.","zh-TW":"餐廳提供各種調味料。"}]', NULL, NULL, 3, 686, NULL),
(687, 'condition', '/kənˈdɪʃn/', 'noun', '{"zh-TW":["條件；狀況"],"en":["the state of something","a stipulation or requirement"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"dit","meaning":"say (說)"},"suffix":{"text":"-ion","meaning":"action (動作)"},"logic":"完全說明的事，即「條件」。"}', 'working conditions / on condition that / terms and conditions', '[{"en":"The equipment is in excellent condition.","zh-TW":"設備狀況良好。"},{"en":"Please read the terms and conditions carefully.","zh-TW":"請仔細閱讀條款和條件。"}]', '{"adjective":"conditional"}', NULL, 3, 687, 302),
(688, 'condominium', '/ˌkɒndəˈmɪniəm/', 'noun', '{"zh-TW":["分層公寓；共管式公寓"],"en":["a building where units are individually owned"]}', NULL, 'buy a condominium / condominium complex', '[{"en":"She purchased a condominium in the downtown area.","zh-TW":"她在市中心購買了一棟共管式公寓。"},{"en":"The condominium complex includes a rooftop terrace.","zh-TW":"共管式公寓大廈設有屋頂露台。"}]', '{"abbreviation":"condo"}', NULL, 4, 688, NULL),
(689, 'conduct', '/kənˈdʌkt/', 'verb', '{"zh-TW":["【主要意義-名詞】行為；品行","【次要意義-動詞】執行；實施（研究/調查）","【次要意義-動詞】指揮（樂團）"],"en":["[primary - noun] the way someone behaves","[secondary - verb] to carry out or manage an activity","[secondary - verb] to direct an orchestra or choir"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"duct","meaning":"lead (引導)"},"logic":"一起引導進行，即「執行」。"}', 'conduct a survey / conduct research / conduct an interview / code of conduct', '[{"en":"The company conducted a thorough review of its supply chain practices.","zh-TW":"公司對其供應鏈做法進行了全面審查。"},{"en":"All employees are expected to conduct themselves professionally.","zh-TW":"所有員工在任何時候都應以專業態度行事。"},{"en":"The HR department will conduct performance reviews next month.","zh-TW":"人力資源部下個月將進行績效評估。"}]', '{"noun":"conductor, conduction","adjective":"conductive"}', '動詞 conduct（重音在第二音節）意為「執行/實施」，句型 conduct + survey/research/interview/review 是 TOEIC 高頻搭配，與名詞 conduct（行為）重音不同。', 3, 689, 89),
(690, 'conductor', '/kənˈdʌktər/', 'noun', '{"zh-TW":["指揮；導體"],"en":["a person who directs an orchestra","a substance that transmits heat or electricity"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"duct","meaning":"lead (引導)"},"suffix":{"text":"-or","meaning":"person who (…的人)"},"logic":"引導大家在一起的人，即「指揮」。"}', 'orchestra conductor / electrical conductor', '[{"en":"The conductor raised his baton.","zh-TW":"指揮舉起了指揮棒。"},{"en":"Copper is an excellent conductor of electricity.","zh-TW":"銅是優良的電導體。"}]', '{"verb":"conduct","noun":"conduction"}', NULL, 3, 690, NULL),
(691, 'conduit', '/ˈkɒndjuɪt/', 'noun', '{"zh-TW":["導管；渠道；中間人"],"en":["a channel or intermediary through which resources or information pass"]}', NULL, 'serve as a conduit / conduit for funds', '[{"en":"The subsidiary served as a conduit for transferring dividends to the parent.","zh-TW":"子公司充當了向母公司轉移股息的渠道。"},{"en":"The trade association acts as a conduit for industry feedback to regulators.","zh-TW":"行業協會充當行業向監管機構反饋的渠道。"}]', NULL, NULL, 3, 691, 844),
(692, 'confer', '/kənˈfɜːr/', 'verb', '{"zh-TW":["商議；授予"],"en":["to discuss something with someone","to grant or bestow"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"fer","meaning":"carry/bring (帶來)"},"logic":"一起帶來討論，即「商議」。"}', 'confer with / confer a degree/title', '[{"en":"I need to confer with my colleagues before deciding.","zh-TW":"我需要與同事商議後再決定。"},{"en":"The university conferred an honorary degree on her.","zh-TW":"大學授予她榮譽學位。"}]', '{"noun":"conference"}', NULL, 2, 692, NULL),
(693, 'confidence', '/ˈkɒnfɪdəns/', 'noun', '{"zh-TW":["信心；信任"],"en":["the feeling of being certain","trust in someone or something"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"fid","meaning":"trust (信任)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"完全信任的狀態，即「信心」。"}', 'consumer confidence / have confidence in / boost confidence', '[{"en":"Consumer confidence has risen for the third consecutive month.","zh-TW":"消費者信心連續第三個月上升。"},{"en":"I have full confidence in the team''s ability.","zh-TW":"我對團隊的能力充滿信心。"}]', '{"adjective":"confident","adverb":"confidently"}', NULL, 4, 693, NULL),
(694, 'confident', '/ˈkɒnfɪdənt/', 'adjective', '{"zh-TW":["有自信的"],"en":["feeling sure about one''s own abilities"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"fid","meaning":"trust (信任)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"完全信任自己的，即「有自信的」。"}', 'feel confident / confident speaker', '[{"en":"She is confident about passing the exam.","zh-TW":"她對通過考試很有信心。"},{"en":"He gave a confident presentation.","zh-TW":"他做了一場充滿自信的報告。"}]', '{"noun":"confidence","adverb":"confidently"}', NULL, 3, 694, NULL),
(695, 'confidential', '/ˌkɒnfɪˈdenʃl/', 'adjective', '{"zh-TW":["機密的；保密的"],"en":["intended to be kept secret"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"fid","meaning":"trust (信任)"},"suffix":{"text":"-ential","meaning":"relating to (有關的)"},"logic":"完全信任下才能知道的，即「機密的」。"}', 'confidential information / strictly confidential / confidential agreement', '[{"en":"This document contains confidential information.","zh-TW":"此文件包含機密資訊。"},{"en":"All client records are treated as strictly confidential.","zh-TW":"所有客戶記錄均被視為嚴格保密。"}]', '{"noun":"confidentiality"}', NULL, 4, 695, 304),
(696, 'confidentiality', '/ˌkɒnfɪˌdɛnʃiˈælɪti/', 'noun', '{"zh-TW":["保密性；機密性"],"en":["the obligation not to disclose certain information"]}', NULL, 'confidentiality agreement / maintain confidentiality', '[{"en":"Employees must sign a confidentiality agreement.","zh-TW":"員工必須簽署保密協議。"},{"en":"The terms of the settlement are subject to strict confidentiality.","zh-TW":"和解條款受到嚴格保密限制。"}]', '{"adjective":"confidential","adverb":"confidentially"}', NULL, 5, 696, 529),
(697, 'confine', '/kənˈfaɪn/', 'verb', '{"zh-TW":["限制；局限於"],"en":["to keep or restrict within certain limits"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"fine","meaning":"end/limit (邊界)"},"logic":"完全限制在邊界內，即「限制」。"}', 'confine to / be confined to', '[{"en":"The discussion should be confined to budget matters.","zh-TW":"討論應限制在預算事項。"},{"en":"The problem is not confined to one department.","zh-TW":"問題不僅限於一個部門。"}]', NULL, NULL, 3, 697, NULL),
(698, 'confirm', '/kənˈfɜːrm/', 'verb', '{"zh-TW":["確認；證實","確認"],"en":["to establish the truth or correctness of","to establish the truth of something"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"firm","meaning":"firm/strong (堅固)"},"logic":"使完全堅固確定，即「確認」。"}', 'confirm a booking/order/appointment; confirm a booking / confirm that / please confirm', '[{"en":"Please confirm your attendance by Friday.","zh-TW":"請在週五前確認您的出席。"},{"en":"The spokesperson confirmed the merger announcement.","zh-TW":"發言人確認了合併公告。"},{"en":"Please confirm your reservation by email.","zh-TW":"請透過電子郵件確認您的預訂。"},{"en":"The test results confirmed the diagnosis.","zh-TW":"檢驗結果確認了診斷。"}]', '{"noun":"confirmation"}', NULL, 3, 698, 17),
(699, 'confirmation', '/ˌkɒnfɜːˈmeɪʃən/', 'noun', '{"zh-TW":["確認；確認書"],"en":["a statement confirming a booking or reservation"]}', NULL, 'booking confirmation / confirmation number', '[{"en":"You will receive a confirmation email after booking.","zh-TW":"預訂後您將收到確認電子郵件。"},{"en":"Please bring your confirmation number to the front desk.","zh-TW":"請攜帶確認號碼前往前台。"}]', '{"verb":"confirm","adjective":"confirmed"}', NULL, 4, 699, NULL);